import 'package:cloud_firestore/cloud_firestore.dart';
import 'package:firebase_auth/firebase_auth.dart';
import 'package:flutter/material.dart';
class ReviewScreen extends StatefulWidget { final String productId; const ReviewScreen({super.key,required this.productId}); @override State<ReviewScreen> createState()=>_ReviewScreenState(); }
class _ReviewScreenState extends State<ReviewScreen>{int rating=5;final comment=TextEditingController();Future<void> save()async{final u=FirebaseAuth.instance.currentUser!;await FirebaseFirestore.instance.collection('reviews').add({'productId':widget.productId,'userId':u.uid,'userName':u.displayName??'Customer','rating':rating,'comment':comment.text.trim(),'createdAt':FieldValue.serverTimestamp()});if(mounted)Navigator.pop(context);}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Write a review')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[DropdownButtonFormField<int>(value:rating,items:List.generate(5,(i)=>DropdownMenuItem(value:i+1,child:Text('${i+1} stars'))),onChanged:(v)=>setState(()=>rating=v!)),const SizedBox(height:15),TextField(controller:comment,maxLines:4,decoration:const InputDecoration(labelText:'Your review')),const SizedBox(height:20),FilledButton(onPressed:save,child:const Text('Submit review'))]));}}
